import { AlchemystAI } from '@alchemystai/sdk';

async function main() {
  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  const runId = process.env.ZEALT_RUN_ID || 'default-run';

  if (!apiKey) {
    console.error('ALCHEMYST_AI_API_KEY is required');
    process.exit(1);
  }

  const userId = `user-${runId}`;
  const sessionA = `session_A-${runId}`;
  const sessionB = `session_B-${runId}`;

  const client = new AlchemystAI({ apiKey });

  // Search memory in session A to check if it's already added
  const searchA = await client.v1.context.memory.search({
    userId,
    sessionId: sessionA,
    query: 'vegan peanut'
  });

  const hasMemory = searchA.memories && searchA.memories.some((m: any) => 
    m.content.toLowerCase().includes('vegan') && m.content.toLowerCase().includes('peanut')
  );

  if (!hasMemory) {
    await client.v1.context.memory.add({
      userId,
      sessionId: sessionA,
      content: 'User is vegan and allergic to peanuts'
    });
  }

  // Parse --query
  const args = process.argv.slice(2);
  const queryIndex = args.indexOf('--query');
  let query = 'What should I eat?';
  if (queryIndex !== -1 && queryIndex + 1 < args.length) {
    query = args[queryIndex + 1];
  }

  // Search memory under session B
  const searchB = await client.v1.context.memory.search({
    userId,
    sessionId: sessionB,
    query
  });

  if (searchB.memories) {
    for (const mem of searchB.memories) {
      if (mem.content.toLowerCase().includes('vegan') && mem.content.toLowerCase().includes('peanut')) {
        console.log(mem.content);
      }
    }
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
EOF
cd /home/user/myproject && npx tsc

